-- Sample database: Hospital
-- GENERATED by app/sample_dbs/generate.py — do not edit by hand

CREATE TABLE doctors (
  id         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  full_name  varchar(100) NOT NULL,
  specialty  varchar(60) NOT NULL,
  phone      varchar(20),
  hired_at   date NOT NULL
);
CREATE TABLE patients (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  full_name   varchar(100) NOT NULL,
  gender      char(1) NOT NULL CHECK (gender IN ('M','F')),
  birth_date  date NOT NULL,
  phone       varchar(20),
  city        varchar(60),
  blood_type  varchar(3)
);
CREATE TABLE appointments (
  id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  patient_id    integer NOT NULL REFERENCES patients(id),
  doctor_id     integer NOT NULL REFERENCES doctors(id),
  scheduled_at  timestamp NOT NULL,
  status        varchar(12) NOT NULL CHECK (status IN ('scheduled','completed','cancelled','no_show')),
  reason        varchar(200)
);
CREATE TABLE treatments (
  id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  appointment_id  integer NOT NULL REFERENCES appointments(id),
  diagnosis       varchar(120) NOT NULL,
  treatment       varchar(200) NOT NULL,
  cost            numeric(10,2) NOT NULL CHECK (cost >= 0)
);
CREATE INDEX idx_appt_patient ON appointments(patient_id);
CREATE INDEX idx_appt_doctor ON appointments(doctor_id);
CREATE INDEX idx_treat_appt ON treatments(appointment_id);

COMMENT ON TABLE doctors IS 'แพทย์ — บางคนยังไม่มีนัด';
COMMENT ON TABLE patients IS 'ผู้ป่วย — phone และ blood_type อาจเป็น NULL';
COMMENT ON TABLE appointments IS 'นัดหมาย — cancelled/no_show/scheduled จะไม่มี treatment';
COMMENT ON TABLE treatments IS 'การรักษา — 1 นัดอาจมีหลายการรักษา';











